window.MONSTER_CHUNK_86 = [{"name":"Adult Silver Dragon","cr":14,"xp":38400,"alignment":"LG","size":"Huge","type":"dragon","subtypes":["cold"],"init":4,"senses":[{"type":"dragon senses"},{"type":"fog vision"}],"auras":["frightful presence (180 ft., DC 23)"],"ac":29,"ac_touch":8,"ac_flat_footed":29,"ac_mods":"+21 natural, -2 size","hp":195,"hd":"17d12+85","hdvalue":17,"fort":15,"ref":12,"will":17,"dr":"5/magic","immunities":["acid","cold","paralysis","sleep"],"sr":25,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":200,"maneuverability":"average"}],"speed_mod":"cloudwalking, graceful flight","melee":"bite +24 (2d8+12), 2 claws +23 (2d6+8), 2 wings +21 (1d8+4), tail slap +21 (2d6+12)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, DC 23, 12d8 cold"},{"type":"crush"},{"type":"paralyzing breath"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil"},{"spell":"feather fall"},{"spell":"fog cloud"}]}],"spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"augury"},{"spell":"cure moderate wounds"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"bless"},{"spell":"divine favor"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"flare"},{"spell":"light"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"stabilize"}]}],"strength":27,"dexterity":10,"constitution":21,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":17,"cmb":27,"cmd":37,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lighting Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Diplomacy","value":25},{"skill":"Fly","value":16},{"skill":"Heal","value":25},{"skill":"Intimidate","value":25},{"skill":"Knowledge (arcana, local, nobility)","value":25},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":25}],"languages":["Auran","Common","Draconic","Dwarven","Giant","Terran"],"sq":[{"type":"change shape"}],"environments":["temperate mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"The scales of this tall, elegant dragon shine like polished silver, and its tail has a feathered appearance.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A silver dragon can assume any animal or humanoid form three times per day as if using polymorph."},{"type":"Cloudwalking","kind":"Su","details":"A very young or older silver dragon can tread on clouds or fog as though on solid ground."},{"type":"Cold Aura","kind":"Su","details":"An old or older silver dragon is surrounded by an aura of cold. All creatures within 5 ft. of the dragon take 1d6 points of cold damage at the beginning of the dragon's turn. An ancient dragon's aura extends to 10 ft. A great wyrm's aura damage increases to 2d6. A silver dragon can suppress or activate this aura at will as a free action."},{"type":"Fog Vision","kind":"Ex","details":"A juvenile or older silver dragon can see perfectly well in fog and clouds."},{"type":"Graceful Flight","kind":"Ex","details":"A young or older silver dragon's aerial maneuverability is one step better than normal."},{"type":"Paralyzing Breath","kind":"Su","details":"Instead of a cone of cold, a silver dragon can breathe a cone of paralyzing gas. Creatures within the cone must succeed on a Fortitude save or be paralyzed for 1d6 rounds plus 1 round per age category of the dragon."},{"type":"Reflective Scales","kind":"Su","details":"Any spell that targets an ancient or older silver dragon but fails to penetrate the silver dragon's spell resistance might be reflected. If the caster level check to penetrate the dragon's spell resistance is failed by 5 or more, the spell is reflected. If the check fails by 4 or less, the spell is merely wasted. This otherwise functions as spell turning."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A silver dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. Very young-detect evil; Juvenile-feather fall; Adult-fog cloud; Old-control winds; Ancient-control weather; Great wyrm-reverse gravity."},{"type":"True Courage","kind":"Ex","details":"A great wyrm silver dragon can fight on through pain and death. When reduced to below 0 hit points, it remains conscious, automatically stabilizes, and can continue to act (although it is staggered). If it takes damage or is the target of a spell that causes its death, it remains alive for 1 round and can act normally (it isn't staggered for this final round). Age Category S pecial Abilities L evel Wyrmling Change shape, cold subtype, - immune to acid, paralyzing breath Very young Cloudwalking, detect evil - Young Graceful flight 1st Juvenile Fog vision, feather fall 3rd Young adult DR 5/magic, spell resistance 5th Adult Frightful presence, fog cloud 7th Mature adult DR 10/magic 9th Old Cold aura, control winds 11th Very old DR 15/magic 13th Ancient Reflective scales, control weather 15th Wyrm DR 20/magic 17th Great wyrm True courage, reverse gravity 19th  A silver dragon can cast cleric spells as arcane spells."}],"description":"Of all the dragons, silvers are the most courageous, holding themselves to a chivalrous code to help the weak, defeat evil, and behave in an honorable manner.","ecology":"","habitat_society":""},{"name":"Adult Umbral Dragon","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"dragon","subtypes":["extraplanar"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (180 ft., DC 23)"],"ac":29,"ac_touch":8,"ac_flat_footed":29,"ac_mods":"+21 natural, -2 size","hp":195,"hd":"17d12+85","hdvalue":17,"fort":15,"ref":10,"will":15,"dr":"5/magic","immunities":["cold","death effects","energy drain","paralysis","sleep"],"sr":25,"speed":[{"type":"land","speed":40},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +23 (2d8+12/19-20), 2 claws +23 (2d6+8), tail slap +21 (2d6+12), 2 wings +21 (1d8+4)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, DC 23, 12d8 negative energy, DC 23"},{"type":"crush"},{"type":"shadow breath","details":"6 Str"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"shadow walk"},{"spell":"vampiric touch"}]}],"spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"inflict serious wounds"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"command undead"},{"spell":"invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"grease"},{"spell":"inflict light wounds"},{"spell":"magic missile"},{"spell":"reduce person"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"disrupt undead"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"read magic"}]}],"strength":27,"dexterity":10,"constitution":21,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":17,"cmb":27,"cmd":37,"cmd_special":"+4 vs. trip","feats":[{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Snatch"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":25},{"skill":"Diplomacy","value":25},{"skill":"Fly","value":16},{"skill":"Knowledge (arcana)","value":25},{"skill":"Knowledge (local)","value":25},{"skill":"Knowledge (planes)","value":25},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":25},{"skill":"Stealth","value":18},{"skill":"Survival","value":25}],"languages":["Abyssal","Common","Draconic","Undercommon","2 more"],"sq":[{"type":"ghost bane"},{"type":"umbral scion"}],"environments":["any"],"organizations":["solitary"],"treasure":"triple","description_visual":"This sleek, dark dragon moves with a disturbing, serpentine grace, its eyes glowing as if lit from within by crimson embers.","group":"Primal Dragon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Although it deals negative energy damage, an umbral dragon's breath weapon doesn't heal undead creatures."},{"type":"Create Shadows","kind":"Su","details":"Any creature slain by an ancient or older umbral dragon rises as a shadow (if 8 HD or less) or greater shadow (if above 8 HD) under the umbral dragon's control 1d4 rounds later."},{"type":"Energy Drain","kind":"Su","details":"A great wyrm umbral dragon deals 1 negative level with each successful bite or claw attack (1 level, DC 32)."},{"type":"Ghost Bane","kind":"Su","details":"A young or older umbral dragon's physical attacks deal damage to incorporeal creatures normally."},{"type":"Umbral Scion","kind":"Ex","details":"Umbral dragons have negative energy affinity and are immune to energy drain and death effects."},{"type":"Shadow Breath","kind":"Su","details":"Three times per day, an adult or older umbral dragon can breathe a cone of shadows. Creatures who fail a Fortitude save are blinded for 1d4 rounds and take 1 point of Str drain per age category possessed by the dragon. A successful save negates the blindness and reduces Str drain to 1d4 points."},{"type":"Spell-Like Abilities","kind":"Sp","details":"An umbral dragon gains the following spell-like abilities, usable at will (unless indicated otherwise) on reaching the listed age category. Young-darkness; Juvenile- vampiric touch; Adult-shadow walk; Old-project image; Ancient-finger of death (3/day), Great wyrm-shades."}],"description":"Cruel and sadistic, umbral dragons prefer the taste of undead flesh or ghostly ectoplasm, yet never turn down opportunities to consume living flesh.","ecology":"","habitat_society":""},{"name":"Adult Vortex Dragon","cr":14,"xp":38400,"alignment":"LN","size":"Huge","type":"dragon","subtypes":["fire"],"init":5,"senses":[{"type":"dragon senses"},{"type":"see in darkness"}],"auras":["alien presence (180 ft., DC 23)"],"ac":30,"ac_touch":9,"ac_flat_footed":29,"ac_mods":"+1 Dex, +21 natural, -2 size","hp":195,"hd":"17d12+85","hdvalue":17,"fort":17,"ref":13,"will":14,"dr":"5/magic","immunities":["fire","paralysis","sleep"],"sr":25,"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"good"}],"melee":"bite +23 (2d8+12/19-20), 2 claws +23 (2d6+8), 2 wings +21 (1d8+4), tail slap +21 (2d6+12)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, 12d8 fire, DC 23"},{"type":"crush"},{"type":"fragmented strike"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"anticipate peril"},{"spell":"entropic shield"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"displacement"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"mirror image"},{"spell":"resist energy"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"comprehend languages"},{"spell":"feather fall"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"message"},{"spell":"read magic"},{"spell":"3 more"}]}],"strength":27,"dexterity":12,"constitution":21,"intelligence":20,"wisdom":19,"charisma":20,"baseatk":17,"cmb":27,"cmd":38,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":25},{"skill":"Diplomacy","value":25},{"skill":"Fly","value":21},{"skill":"Intimidate","value":25},{"skill":"Knowledge (arcana)","value":25},{"skill":"Knowledge (geography)","value":25},{"skill":"Knowledge (planes)","value":25},{"skill":"Knowledge (religion)","value":25},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":24},{"skill":"Spellcraft","value":25}],"languages":["Abyssal","Auran","Celestial","Common","Draconic","Infernal"],"sq":[{"type":"agile"},{"type":"galactic emissary"},{"type":"no breath"},{"type":"starflight"}],"environments":["any vacuum"],"organizations":["solitary"],"treasure":"triple","description_visual":"This dragon twists and whips with near untraceable speed. Its horns, crests along its neck, and wings emit a glow like starlight.","group":"Outer Dragon","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Agile","kind":"Ex","details":"Vortex dragons have good maneuverability when flying regardless of their age or size."},{"type":"Alien Presence","kind":"Su","details":"A vortex dragon's alien presence bends space. A creature that fails its saving throw treats all other creatures as if they were under the effects of blur (or displacement if the target has 4 or fewer Hit Dice) for 5d6 rounds."},{"type":"Collapsing Breath","kind":"Su","details":"Instead of a cone of fire, an ancient or older vortex dragon can suck a single target into its maw. If the target fails its Reflex save (DC equal to breath weapon), it is swallowed whole and takes 6d6 points of bludgeoning damage per round. A creature can cut itself out by dealing 30 points of damage with a light or one-handed piercing or slashing weapon. A vortex dragon's interior has an AC of 26."},{"type":"Fragmented Strike","kind":"Su","details":"An adult or older vortex dragon can strike with its bite through a rift in space. This allows it to make its bite attack against a target anywhere within the radius of its alien presence as long as the dragon can see the creature. This doesn't apply to attacks of opportunity."},{"type":"Galactic Emissary","kind":"Su","details":"A young or older vortex dragon halves the time of any starflight journey. In addition, it's immune to any effect that bars extradimensional travel."}],"description":"Vortex dragons are the undisputed masters of travel across the galaxies, serving as messengers and observers for the greatest outer dragons and godlike entities in the great beyond.","ecology":"","habitat_society":""},{"name":"Ankou","cr":14,"xp":38400,"alignment":"LE","size":"Large","type":"fey","subtypes":["extraplanar"],"init":13,"senses":[{"type":"blindsense","modifier":"120 ft."},{"type":"low-light vision"}],"ac":31,"ac_touch":19,"ac_flat_footed":21,"ac_mods":"+9 Dex, +1 dodge, +12 natural, -1 size","hp":133,"hd":"14d6+84","hdvalue":14,"fort":10,"ref":18,"will":13,"dr":"10/cold iron","speed":[{"type":"fly","speed":90,"maneuverability":"perfect"}],"melee":"2 claws +14 (1d6+8), tail slap +9 (1d8+4 plus bleed), 2 wings +9 (1d8+4 plus bleed)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"2d6"},{"type":"cold iron killer"},{"type":"shadow doubles"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"ray of exhaustion"},{"spell":"silence","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"circle of death"},{"spell":"discern location"},{"spell":"prismatic spray"}]},{"frequency":"3/day","spells":[{"spell":"dimensional anchor"},{"spell":"greater teleport"},{"spell":"true seeing"}]}],"strength":26,"dexterity":28,"constitution":22,"intelligence":17,"wisdom":19,"charisma":25,"baseatk":7,"cmb":16,"cmd":36,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Stance"},{"feat":"Wind Stance"}],"skills":[{"skill":"Bluff","value":24},{"skill":"Escape Artist","value":26},{"skill":"Fly","value":32},{"skill":"Intimidate","value":21},{"skill":"Knowledge (nature)","value":20},{"skill":"Knowledge (planes)","value":17},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":21},{"skill":"Stealth","value":22}],"languages":["Common","Sylvan (can't speak any language)","telepathy 100 ft."],"environments":["any (primal land of fey)"],"organizations":["solitary"],"treasure":"standard","description_visual":"Cloaked by wings of darkness, this horrific, skeletal creature appears to burn from within.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Cold Iron Killer","kind":"Su","details":"All of an ankou's natural weapons are treated as cold iron for the purpose of overcoming damage reduction."},{"type":"Shadow Doubles","kind":"Su","details":"Once per day as a free action, an ankou can conjure up to four shadowy duplicates, which appear anywhere within 60 ft. of the ankou and last a number of rounds equal to the ankou's Charisma modifier (typically 7 rounds). These shadow doubles are identical to the original in all respects except that when conjured they have a number of hit points equal to 20% of the true ankou's total hit points (26 hit points if conjured by an ankou with full hit points). The doubles have all of the true ankou's melee attacks and abilities, except they can't create more shadow doubles or use the ankou's spell-like abilities except for deeper darkness. Any creature that interacts with a shadow double can attempt a Will save to disbelieve the duplicate (DC 10 + 1/2 the ankou's Hit Dice + the ankou's Charisma modifier, typically DC 24). Against a creature that recognizes a shadow double for what it is, the double functions as a shadow conjuration. Shadow doubles take double damage from spells with the light descriptor. If the true ankou is slain, is rendered unconscious, or is ever more than 120 ft. from a shadow double, the duplicates instantly vanish."}],"description":"Ankous are assassins for powerful fey nobles, sent to kill, terrify, and torture. They never speak, only telepathically whisper their lord's verdict to victims. A typical ankou is 10 ft. tall and has an 8-foot wingspan, but weighs less than 100 pounds.","ecology":"","habitat_society":""},{"name":"Astral Deva","cr":14,"xp":38400,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["angel","extraplanar","good"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["protective aura"],"ac":29,"ac_touch":14,"ac_flat_footed":25,"ac_mods":"+4 Dex, +15 natural | +4 deflection vs. evil","hp":172,"hd":"15d10+90","hdvalue":15,"fort":16,"ref":13,"will":11,"save_mods":"+4 vs. poison, +4 vs. evil","defensive_abilities":["uncanny dodge"],"dr":"10/evil","immunities":["acid","cold","petrification"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":25,"speed":[{"type":"land","speed":50},{"type":"fly","speed":100,"maneuverability":"good"}],"melee":"+2 disrupting warhammer +26 (1d8+14/x3 plus stun) or slam +23 (1d8+12)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"continual flame"},{"spell":"detect evil"},{"spell":"discern lies"},{"spell":"dispel evil"},{"spell":"dispel magic"},{"spell":"holy aura"},{"spell":"holy smite"},{"spell":"holy word"},{"spell":"invisibility","details":"self only"},{"spell":"plane shift"},{"spell":"remove curse"},{"spell":"remove disease"},{"spell":"remove fear"}]},{"frequency":"1/day","spells":[{"spell":"blade barrier"},{"spell":"heal"}]},{"frequency":"7/day","spells":[{"spell":"cure light wounds"},{"spell":"see invisibility"}]}],"strength":26,"dexterity":19,"constitution":21,"intelligence":18,"wisdom":18,"charisma":23,"baseatk":15,"cmb":23,"cmd":37,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (warhammer)"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Craft (any one)","value":22},{"skill":"Diplomacy","value":24},{"skill":"Fly","value":26},{"skill":"Intimidate","value":24},{"skill":"Knowledge (planes)","value":22},{"skill":"Knowledge (religion)","value":19},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Stealth","value":22}],"languages":["Celestial","Draconic","Infernal","truespeech"],"sq":[{"type":"change shape","details":"alter self"}],"environments":["any good-aligned plane"],"organizations":["solitary","pair","squad (3-6)"],"treasure":"double (+2 disrupting warhammer)","description_visual":"This tall, human-like creature has long, feathery wings and a gentle inner radiance that makes it difficult to look directly at.","group":"Astral Deva Angel","source":"PFRPG Bestiary","special_abilities":[{"type":"Stun","kind":"Su","details":"If an astral deva strikes an opponent twice in one round with its warhammer, that creature must succeed on a DC 25 Fortitude save or be stunned for 1d6 rounds. The save DC is Strength-based."},{"type":"Uncanny Dodge","kind":"Ex","details":"This ability functions identically to the rogue ability. If a deva gains uncanny dodge from a class level, he instead gains improved uncanny dodge."}],"description":"Astral devas are messengers of the gods of good. They watch over planar travelers and sponsor powerful mortals, pushing them to take on good causes. A typical astral deva looks human except for its wings, though some look like other humanoid races and a rare few have even more unusual forms. An astral deva is 7-1/2 ft. tall and weighs 250 pounds. Astral devas are usually created by deities from the souls of good mortals, though some souls spontaneously transform into astral devas without the intervention of a deity. Their skills and abilities make them excellent scouts and elite agents for celestial armies. They often carry long, flowing scrolls upon which are writ messages and judgments from the gods. An astral deva's scrolls frequently contain hints of prophecies and major events yet to come, and as such the devas are fiercely protective of the contents of these scrolls and let none, not even other astral devas, peruse them.","ecology":"","habitat_society":""},{"name":"Augnagar","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"outsider","subtypes":["chaotic","evil","extraplanar","qlippoth"],"init":3,"senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"scent"},{"type":"true seeing"}],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"-1 Dex, +22 natural, -2 size","hp":203,"hd":"14d10+126","hdvalue":14,"fort":18,"ref":10,"will":9,"dr":"10/lawful","immunities":["cold","poison","mind-affecting effects"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":50},{"type":"climb","speed":50},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"bite +23 (2d6+11 plus 1d8 bleed and rotting curse),   3 claws +23 (1d8+11 plus 1d8 bleed)","space":"15 ft.","reach":"15 ft. (30 ft. with claws)","special_attacks":[{"type":"bleed"},{"type":"horrific appearance","details":"DC 21"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"1/day","spells":[{"spell":"waves of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"dimension door"},{"spell":"protection from law"}]}],"strength":32,"dexterity":9,"constitution":28,"intelligence":5,"wisdom":20,"charisma":19,"baseatk":14,"cmb":27,"cmd":36,"cmd_special":"+8 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":19},{"skill":"Fly","value":12},{"skill":"Perception","value":22},{"skill":"Stealth","value":24}],"languages":["Abyssal","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This enormous, spider-like creature has three clawed tails and eight legs connected by leathery webs of flesh.","group":"Qlippoth","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to an augnagar's horrific appearance are driven momentarily insane. This results in 2 points of Charisma damage and leaves the victim confused for 1d3 rounds."},{"type":"Rotting Curse","kind":"Su","details":": Bite—injury; Save Fort DC 26; Frequency 1/ day; Effect 1d6 Con drain plus constant stench. A creature that suffers the rotting curse imparted by an augnagar's bite displays hideous, festering wounds that exude a horrific stench. This functions as the stench universal monster rule, save that it affects all creatures except those that are immune to poison. The victim of this curse receives no saving throw to avoid becoming sickened by the stench, but other creatures can attempt a DC 26 Fortitude save to negate this condition-those who fail remain sickened as long as they remain within 30 ft. of the cursed victim. The horrific stench also imparts a -8 penalty on all Stealth checks made by the cursed victim. The save DC is Constitution-based."}],"description":"The immense augnagar is relatively slow-witted. As an outsider, it doesn't need to eat to survive, yet it remains ravenous and feeds on anything it can overpower. The augnagar prefers the taste of well-rotted flesh—particularly rotted demon flesh-and the horrific curse its bite imparts flavors its meals perfectly. Yet the augnagar's favorite feast is of a much more cannibalistic type. These creatures find the flesh of their own kind to be the greatest delicacy. When an augnagar feeds upon enough of its own kind, it grows enormously bloated such that it can no longer fly, at which point it uses its clawed tails to tear its body apart in a frenzy of self-destruction. From this storm of torn fat and shredded viscera emerges a fully grown thulgant qlippoth-a creature similar in shape to an augnagar, yet much more intelligent and even more dangerous.\n\nAn augnagar has a wingspan of 30 ft. and weighs 6,000 pounds.","ecology":"","habitat_society":""},{"name":"Bodythief","cr":14,"xp":38400,"alignment":"LE","size":"Gargantuan","type":"plant","init":-1,"senses":[{"type":"low-light vision"}],"ac":26,"ac_touch":1,"ac_flat_footed":25,"ac_mods":"-5 Dex, +25 natural, -4 size","hp":230,"hd":"20d8+140","hdvalue":20,"fort":19,"ref":1,"will":11,"defensive_abilities":["vexing vines"],"immunities":["plant traits","sonic"],"resists":[{"type":"cold","value":20}],"speed":[{"type":"land","speed":5}],"melee":"bite +23 (2d8+12 plus grab), 4 tentacles +21 (1d8+6 plus grab)","space":"20 ft.","reach":"20 ft. (40 ft. with tentacles)","special_attacks":[{"type":"breath weapon","details":"80-ft. line, 12d6 acid damage, Reflex DC 27 half, usable every 1d4 rounds"},{"type":"swallow whole","details":"4d6 acid damage plus absorb essence; AC 22, 23 hp"},{"type":"transfer"}],"strength":34,"dexterity":1,"constitution":25,"intelligence":21,"wisdom":16,"charisma":14,"baseatk":15,"cmb":31,"cmb_special":"+4 vs. disarm, +4 vs. grapple, +2 vs. trip","cmd":38,"cmd_special":"+2 vs. disarm, can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Greater Disarm"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Trip"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Skill Focus (Knowledge [nature])"}],"skills":[{"skill":"Disguise","value":27},{"skill":"Knowledge (geography)","value":20},{"skill":"Knowledge (history)","value":20},{"skill":"Knowledge (local)","value":20},{"skill":"Knowledge (nobility)","value":20},{"skill":"Knowledge (nature)","value":31},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":27}],"languages":["Common","Dwarven","Elven","Orc","Sylvan (can't speak any language)","telepathy 1","000 ft. (with spawn only)"],"sq":[{"type":"spawn pod creature"}],"environments":["temperate forests","warm forests"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This immense plant has jaws inside its central flower and vines that thresh the air. Its ovular seedpods throb like beating hearts.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Absorb Essence","kind":"Su","details":"Creatures in a bodythief's stomach gain 4 negative levels (Fortitude DC 27 half) each round at the start of the bodythief's turn. A check to remove a negative level gained in this way is also DC 27. If the creature dies from the negative levels, its body disintegrates and the bodythief absorbs its life essence. This is a death effect."},{"type":"Spawn Pod Creature","kind":"Su","details":"Once a bodythief has absorbed the life essence of a Large or smaller creature, it can begin growing a duplicate of that creature as a free action. Growing a Tiny or smaller duplicate takes 1 round, a Small duplicate 3 rounds, a Medium duplicate 5 rounds, and a Large duplicate 10 rounds. Duplicates are identical to the creature whose life essence has been devoured, but they gain the pod creature template. They closely resemble the original creature and retain all its memories. The newly created spawn has none of the original creature's equipment, though the bodythief can vomit forth any surviving swallowed gear as a move action. As the duplicate hatches, the bodythief makes a Disguise check to determine the resemblance to the original. The duplicate must be grown within 24 hours of the original's digestion, or its essence and memories dissipate. Only a single duplicate can made of any given creature."},{"type":"Transfer","kind":"Ex","details":"A bodythief can transfer a creature grappled with a tentacle to its mouth with a move action and a successful grapple combat maneuver check."},{"type":"Vexing Vines","kind":"Ex","details":"Each of the bodythief's tentacle vines plus its bite attack can deliver its own attack of opportunity, giving the bodythief five attacks of opportunity per round. It cannot deliver attacks of opportunity with a portion of its body being used to grapple. The bodythief can give up an attack of opportunity with a tentacle to deflect a missile as though it had the Deflect Arrows feat."}],"description":"Plants of frightfully advanced intellect, bodythieves cannot abide the irrationalities of other intelligent life, particularly emotions. They seek to create a world of perfect order by replacing other life forms with nearly perfect duplicates spawned by the bodythief itself. Indeed, these duplicates improve on the originals, as they can communicate telepathically with the bodythief, and they lack wasteful emotions. Individual bodythieves vary as to their specific plans for building a perfect society of duplicates. A common, though recognized, flaw in their plans is the infertility of their duplicates. To maintain a stable society, the bodythieves must capture creatures to replace the inevitable loss of healthy duplicates. Bodythieves are nearly immobile, though they can drag themselves along with their vines in extremis. When they must move large distances, they enlist the aid of their spawn.","ecology":"","habitat_society":""},{"name":"Brass Golem","cr":14,"xp":38400,"alignment":"N","size":"Huge","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"see invisibility"}],"ac":30,"ac_touch":8,"ac_flat_footed":30,"ac_mods":"+22 natural, -2 size","hp":150,"hd":"20d10+40","hdvalue":20,"fort":6,"ref":6,"will":7,"dr":"15/adamantine","immunities":["construct traits","fire","magic"],"speed":[{"type":"land","speed":40}],"melee":"brass falchion +29 (3d6+11/18-20 plus 2d6 fire), slam +29 (2d6+11 plus 2d6 fire)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"DC 20"},{"type":"heat","details":"2d6 fire"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]}],"strength":32,"dexterity":11,"wisdom":13,"charisma":1,"baseatk":20,"cmb":33,"cmd":43,"sq":[{"type":"death throes"},{"type":"brass falchion"}],"environments":["any"],"organizations":["solitary","watch (2-4)"],"treasure":"none","description_visual":"This towering brass statue, built to resemble an evil horned humanoid, carries a gigantic curved sword in its metal fists.","group":"Golem","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Brass Falchion","kind":"Ex","details":"A brass golem's falchion deals damage as a Huge falchion, but is actually a primary natural attack, not a manufactured weapon, and cannot be disarmed."},{"type":"Breath Weapon","kind":"Su","details":"As a free action once every 1d4 rounds, a brass golem can expel a cloud of smoke and cinders that fills a 20-foot cube. This functions as an incendiary cloud that persists for 1d6 rounds, dealing 6d6 points of fire damage (DC 20 Reflex for half). The save DC is Constitution-based."},{"type":"Death Throes","kind":"Ex","details":"A brass golem explodes when it is destroyed. All creatures within 30 ft. of the golem take 12d8 points of fire damage (DC 20 Reflex for half). The save DC is Constitution-based."},{"type":"Immunity to Magic","kind":"Ex","details":"A brass golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature. • A magical attack that deals cold damage slows a brass golem (as per the slow spell) for 1d6 rounds, with no saving throw. • A magical attack that deals fire damage breaks any slow effect on the golem and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A brass golem gets no save against fire effects."}],"description":"Implacable automatons of elemental fire and extraplanar brass, brass golems stand sentinel over the palaces, treasuries, and harems of their creators. Brass golems are 24 ft. tall and weigh 18,000 pounds.\n\nConstruction\n\nCrafting a brass golem requires 18,000 pounds of brass, cast with several rare mineral solutions and ore compounds that cost at least 20,000 gp.\n\nBRASS GOLEM\n\nCL 17th; Price 180,000 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, incendiary cloud, limited wish, see invisibility, creator must be caster level 17th; Skill Craft (armor) or Craft (blacksmithing) DC 22; Cost 100,000 gp","ecology":"","habitat_society":""},{"name":"Crag Linnorm","cr":14,"xp":38400,"alignment":"CE","size":"Gargantuan","type":"dragon","init":8,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"true seeing"}],"ac":29,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+4 Dex, +19 natural, -4 size","hp":202,"hd":"15d12+105","hdvalue":15,"hp_mods":["regeneration 10 (cold iron)"],"fort":16,"ref":15,"will":13,"defensive_abilities":["freedom of movement"],"dr":"15/cold iron","immunities":["curse effects","fire","mind-affecting effects","paralysis","poison","sleep"],"sr":25,"speed":[{"type":"land","speed":40},{"type":"fly","speed":100,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +23 (2d8+12/19-20 plus poison), 2 claws +23  (1d8+12), tail +18 (2d6+6 plus grab)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"breath weapon"},{"type":"constrict","details":"tail, 2d6+18"},{"type":"death curse"}],"strength":34,"dexterity":18,"constitution":25,"intelligence":5,"wisdom":18,"charisma":21,"baseatk":15,"cmb":31,"cmb_special":"+4 vs. grapple","cmd":45,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":16},{"skill":"Perception","value":22},{"skill":"Swim","value":38}],"languages":["Aklo","Draconic","Sylvan"],"environments":["cold hills"],"organizations":["solitary"],"treasure":"triple","description_visual":"This immense, wingless dragon rears up on a serpentine body. Its triple tail and powerful talons swipe at the air.","group":"Linnorm","source":"PFRPG Bestiary","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a standard action, a crag linnorm can expel a 120-foot line of magma, dealing 15d8 points of fire damage to all creatures struck (Reflex DC 24 halves). This line of magma remains red-hot for 1 round after the linnorm creates it. Creatures that took damage on the first round take 6d6 fire damage the second round (Reflex DC 24 negates), as does any creature that walks across the line of magma. If the magma was expelled while the linnorm was airborne, it instead rains downward during the second round as a sheet of fire no more than 60 ft. high that does 6d6 damage (Reflex DC 24 negates) to any creature that passes through it. On the third round, the line of magma cools to a thin layer of brittle stone that quickly degrades to powder and sand over the course of several hours; magma that's turned to a sheet of fire is consumed entirely during the second round, leaving behind only a stain of smoke in the air that swiftly disperses. The save DC is Constitution-based."},{"type":"Death Curse","kind":"Su","details":"When a creature slays a crag linnorm, the slayer is affected by the curse of fire. Curse of Fire: save Will DC 22; effect creature gains vulnerability to fire. The save DC is Charisma-based."},{"type":"Freedom of Movement","kind":"Ex","details":"A crag linnorm is under the constant effect of freedom of movement, as per the spell of the same name. This effect cannot be dispelled."},{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 24; frequency 1/round for 10 rounds; effect 2d6 fire damage and 1d4 Con drain; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"True Seeing","kind":"Ex","details":"A crag linnorm has constant true seeing, as per the spell of the same name."}],"description":"Like all linnorms, the deadly crag linnorm is a powerful, primeval dragon, a denizen of the wild regions far north of where most civilizations dare to tread. The crag linnorm is among the weakest of its kind, yet still a devastating predator in its own right. Favored, if not by the gods, then by some primal intelligence of the mysterious world of the fey, the linnorm bestows a powerful curse on any who manage to slay it. A crag linnorm is 60 ft. long and weighs 12,000 pounds.","ecology":"","habitat_society":""},{"name":"Demilich","cr":14,"xp":38400,"alignment":"NE","size":"Tiny","type":"undead","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"ac":25,"ac_touch":21,"ac_flat_footed":21,"ac_mods":"+3 Dex, +1 dodge, +4 natural, +5 profane, +2 size","hp":142,"hd":"15d8+75","hdvalue":15,"fort":15,"ref":15,"will":8,"defensive_abilities":["channel resistance +5","rejuvenation","unholy grace"],"dr":"20/-","immunities":["acid","cold","electricity","magic","polymorph","undead traits"],"weaknesses":["torpor","vorpal susceptibility"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"devour soul"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"greater bestow curse"},{"spell":"telekinesis"},{"spell":"wail of the banshee","details":"20-ft.-radius spread centered on the demilich"}]}],"strength":6,"dexterity":17,"intelligence":21,"wisdom":20,"charisma":21,"baseatk":11,"cmb":12,"cmd":30,"feats":[{"feat":"Ability Focus (devour soul)"},{"feat":"Alertness"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Flyby Attack","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Fly","value":23},{"skill":"Knowledge (arcana)","value":23},{"skill":"Knowledge (dungeoneering)","value":20},{"skill":"Knowledge (history)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Spellcraft","value":23},{"skill":"Stealth","value":24}],"languages":["Abyssal","Aklo","Common","Draconic","Giant","Infernal"],"environments":["any"],"organizations":["solitary"],"treasure":"double","description_visual":"Glittering jewels encrust this leering skull as it floats up into the air on a swirling vortex of dust and shimmering magic.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Devour Soul","kind":"Su","details":"As a standard action with a range of 300 ft., a demilich can imprison the soul of a living creature within one of 10 special gems embedded in its skull. If the target succeeds at a DC 24 Fortitude save, it gains two permanent negative levels. If it fails, its soul is immediately drawn into one of the gems in the demilich's skull. The soul remains trapped within the gem, visible as but a gleam except under true seeing. The soulless body corrupts and decays rapidly, reducing to dust in a single round. As long as the dead creature's soul remains trapped in the gemstone, it cannot be restored to life via any means save direct divine intervention. Gems with souls trapped in them can be retrieved from a destroyed demilich, at which point they can either be crushed to release any souls within to their afterlife or used in the place of the usual material components to restore the soul and body with resurrection or true resurrection. After 24 hours, the demilich can choose to consume any soul trapped in a gem, healing it 1d6 hit points per Hit Die of the soul, at which point only miracle or wish can restore the dead creature to life. The save DC is Charisma-based, and includes a +2 bonus for the Ability Focus feat."},{"type":"Greater Bestow Curse","kind":"Sp","details":"This spell-like ability functions like bestow curse, but can have one of the following effects: -12 to one ability score; -6 to two ability scores; -8 penalty on attack rolls, saves, and checks; or a 25% chance to act normally. This ability is treated as a 6th-level spell."},{"type":"Immunity to Magic","kind":"Su","details":"A demilich is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells function differently against the creature, as noted below. • A dispel evil spell deals 2d6 points of damage, with no saving throw. • Holy smite affects a demilich normally. • A power word kill spoken by an ethereal caster deals 50 points of damage to the demilich if it fails a Fortitude save (with a DC determined as though the spell allowed a saving throw). • A shatter spell deals 1d6 points of damage per two caster levels (maximum 10d6), with no saving throw."},{"type":"Rejuvenation","kind":"Su","details":"A destroyed demilich reforms in 2d6 days. To permanently destroy a demilich, holy water must be poured over its remains within the area of a hallow spell. To complete the destruction, holy word or dispel evil must be cast. If the caster succeeds at a caster level check with a DC equal to 10 + the demilich's Hit Dice, the demilich is permanently destroyed."},{"type":"Telekinetic Storm","kind":"Su","details":"As a special use of its telekinesis spell-like ability, a demilich can churn up its treasure, dust, bones, and other loose debris in the area into a whirling storm about its skull. The storm obscures vision as a fog cloud within a 20-foot spread centered on the demilich's skull. Creatures within the storm take 12d6 points of bludgeoning damage per round on the demilich's turn (Reflex DC 20 half). The demilich can maintain the storm indefinitely by concentrating."},{"type":"Torpor","kind":"Ex","details":"A demilich takes no actions against intruders unless its remains or treasure are disturbed."},{"type":"Unholy Grace","kind":"Su","details":"A demilich gains a bonus on saves and a profane bonus to AC equal to its Charisma modifier."},{"type":"Vorpal Susceptibility","kind":"Ex","details":"Vorpal weapons of any kind ignore a demilich's damage reduction."}],"description":"In their endless years of unlife, some liches lose themselves in introspection, and can no longer rouse themselves to face the endless march of days. Still others cast their consciousness far from their bodies, wandering planes and realities far beyond mortal ken. Absent the vitality\n\nof the soul, such a lich's physical form succumbs to decay over the centuries. In time, only the lich's skull remains intact. Yet the bonds of undeath keep the lich's remains from final dissolution. Vestiges of the lich's intellect remain within the skull, and wake to terrible wrath should it be disturbed. Traces of the lich's will to live strengthen the skull, rendering it harder than any steel. The lich's greed and lust for power manifest in the growth of gems in its skull. Lastly, though only the barest remnants of the lich's eldritch might survive, a demilich aroused to anger still retains enough power to flense the very soul from any defiling its final rest.\n\nThe lich's phylactery invariably fails during the slow decline of lich into demilich, losing its last vestiges of enchantment if not crumbling into dust with the lich's body. But even without the preserving power of the phylactery, demiliches retain a tenacious grip on existence. Only powerful and precise use of magic can permanently destroy a demilich and its remains.\n\nTo the unwary adventurer, a demilich looks like nothing more than dust and bones within the lich's former sanctum. Indeed, until disturbed, a demilich has only the vaguest awareness of intruders, and ignores their presence. Any attempt to steal the demilich's possessions, disturb its remains, or harm its domain rouses the demilich's slumbering mind, causing it to rise up in the air and voice its wail of the banshee before again settling to the ground. Should the interlopers relent, the skull returns to its torpor. But if they persist, the skull rises again, not to rest again until all in its sight have perished. Fortunately for intruders, demiliches never pursue those wise enough flee.\n\nBECOMING A DEMILICH\n\nMost demiliches achieved their state through apathy, not volition. For each decade that a demilich fails to stir itself to meaningful action, there is a 1% cumulative chance that its corporeal body decays into dust, save for the skull. Any return to activity resets the chance of transformation to 0%. Once the lich's body decays, the lich's intellect returns to its phylactery as normal. However, the skull rejects the return of the lich's consciousness, keeping the lich trapped in its deteriorating phylactery for 1d10 years. If during that time the lich's remains are destroyed or scattered (for example, by wandering adventurers), the lich's phylactery forms a new body and the intellect leaves the phylactery as normal, returning the lich to life. But if the lich's remains survive unperturbed, the phylactery's magic fails catastrophically, releasing the lich's soul and causing 5d10 points of damage to the phylactery. Regardless of whether or not the phylactery physically survives, the energies released by its failure channel into the lifeless skull of the lich, allowing the last remnants of the lich's soul to transform it into a demilich. The lich's\n\nsoul itself either is utterly destroyed, reaches its final reward or punishment, or is condemned to wander the edges of the multiverse forever.\n\nFor wandering liches, the process is similar, but based on the number of decades the lich spends without its intellect returning to its body. While the lich's body still decays, its mind remains at large, only becoming trapped in the phylactery if the lich tries to return during the period in which its body has failed, but it has not yet become a demilich. Should the lich's phylactery fail before the wandering lich returns, the skull becomes a demilich, and the lich's mind is doomed to wander until the end of days.\n\nAWAKENED DEMILICHES\n\nUnder exceptional conditions, a lich's full consciousness survives its transformation into a demilich, or a lich's wandering intellect manages to return to its jeweled skull. Such creatures are awakened demiliches, and combine the powers and near-invulnerability of a demilich with the mind and spellcasting prowess of a lich. An awakened demilich has the full spellcasting abilities of the lich it was before, and gains Eschew Materials and Still Spell as bonus feats. Awakened liches keep their original lich Hit Dice, and any mental attributes that are higher than the demilich's minimums. They otherwise have all the special abilities and defenses of a demilich, except torpor, and no abilities of the original lich beyond spellcasting and mental attributes. An awakened demilich has a CR of 16, or the CR of the original lich + 3, whichever is higher.","ecology":"","habitat_society":""},{"name":"Handmaiden Devil","cr":14,"xp":38400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"ac":31,"ac_touch":17,"ac_flat_footed":24,"ac_mods":"+7 Dex, +14 natural","hp":187,"hd":"15d10+105","hdvalue":15,"fort":16,"ref":16,"will":12,"dr":"10/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":25,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +22 (2d8+7/19-20/x3), 2 tentacles +20 (1d6+3 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacle)","special_attacks":[{"type":"tentacle cage","details":"4d8+10 bludgeoning, AC 17, 18 hp"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"spider climb"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"dispel good"},{"spell":"enthrall"},{"spell":"greater teleport","details":"self plus 1 entrapped creature and 50 lbs. of goods only"},{"spell":"persistent image"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 5, 3 erinyes 65%"}]},{"frequency":"3/day","spells":[{"spell":"black tentacles"},{"spell":"charm monster"}]}],"strength":24,"dexterity":25,"constitution":25,"intelligence":22,"wisdom":21,"charisma":20,"baseatk":15,"cmb":23,"cmd":39,"feats":[{"feat":"Acrobatic Steps"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Multiattack"},{"feat":"Nimble Moves"},{"feat":"Strike Back"}],"skills":[{"skill":"Acrobatics","value":25,"special":"+29 jump"},{"skill":"Bluff","value":23},{"skill":"Diplomacy","value":23},{"skill":"Disguise","value":23},{"skill":"Escape Artist","value":22},{"skill":"Fly","value":14},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (planes)","value":24},{"skill":"Perception","value":23},{"skill":"Perform (sing)","value":23},{"skill":"Sense Motive","value":23},{"skill":"Spellcraft","value":21},{"skill":"Stealth","value":25}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"sq":[{"type":"agile grappler"}],"environments":["any (Hell)"],"organizations":["solitary","retinue (1 gylou and 2d4 erinyes)","cortege (1-4 gylous and 2d10 erinyes)"],"treasure":"standard","description_visual":"Twin tentacles stretch from the crown of this feminine fiend's head, while her lower body blooms in a gown of writhing tendrils.","group":"Devil","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Agile Grappler","kind":"Ex","details":"A gylou doesn't gain the grappled condition if she grapples a foe."},{"type":"Tentacle Cage","kind":"Su","details":"If a gylou successfully grapples a creature, she transfers that creature into her lower body's nest of cage-like tentacles. This works like swallow whole. The gylou's tentacles are AC 17 and have 18 hp for the purpose of an entrapped creature cutting itself out. A gylou's tendrils heal quickly, allowing her to use this ability 1 round after a creature cuts itself free."}],"description":"Known as handmaiden devils, Mothers of Pain, and Maids of Miscarriage, gylous attend to the whims and schemes of Hell's few female overlords. Like manipulative matrons amid decadent mortal courts, these deceivers hide their fathomless evil beneath illusions of beauty, graciousness, and tradition. Gylous particularly loathe children. It's said that the persistent cry of a babe can sometimes cause these fiends to abandon their illusions and viciously attack.\n\nAs greater devils, gylous can command many lesser devils, yet harbor an exclusive favoritism for erinyes. A gylou weighs 160 pounds and stands stiff ly at 5-1/2 ft.- though many wear their head-sprouting tentacles in tall, elaborate coiffures.","ecology":"","habitat_society":""},{"name":"Feranth","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"magical beast","init":-2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"120 ft."}],"ac":29,"ac_touch":6,"ac_flat_footed":29,"ac_mods":"-2 Dex, +23 natural, -2 size","hp":218,"hd":"19d10+114","hdvalue":19,"fort":16,"ref":9,"will":11,"defensive_abilities":["ferocity","hardened body"],"dr":"5/adamantine","speed":[{"type":"land","speed":50},{"type":"burrow","speed":30}],"melee":"bite +25 (2d6+8), 2 claws +25 (1d8+8), gore +25 (2d6+8 plus push)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"ambush"},{"type":"burrowing charge"},{"type":"push","details":"gore, 10 ft."},{"type":"quick strike"},{"type":"skull-splitting roar"}],"strength":26,"dexterity":7,"constitution":20,"intelligence":4,"wisdom":17,"charisma":7,"baseatk":19,"cmb":29,"cmb_special":"+2 vs. bull rush","cmd":37,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Stunning Assault"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+18 when jumping"},{"skill":"Climb","value":15},{"skill":"Perception","value":16}],"environments":["warm deserts","warm mountains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"A droning hum announces the presence of this enormous horned beast. Powerful muscles ripple just beneath its mottled black hide.","source":"AP 90","special_abilities":[{"type":"Ambush","kind":"Ex","details":"When a feranth charges, instead of making an attack at the end of the charge, it can instead use its skull-splitting roar ability, although the DC to resist this ability is 4 lower when the ability is used in this fashion."},{"type":"Burrowing Charge","kind":"Ex","details":"A feranth can use the charge and run actions while burrowing."},{"type":"Hardened Body","kind":"Ex","details":"A feranth's natural attacks count as adamantine for the purpose of overcoming damage reduction and hardness."},{"type":"Quick Strike","kind":"Ex","details":"Whenever a feranth successfully dazes a creature using its skull-splitting roar ability, it can make an attack of opportunity against that creature. A feranth can use this ability against only one target per round, no matter how many creatures it successfully dazes."},{"type":"Skull-Splitting Roar","kind":"Ex","details":"As a standard action, a feranth can unleash a terrible roar, affecting all creatures in a 15-foot cone. Any creatures in the area of the cone must succeed at a DC 24 Fortitude save or be dazed for 1 round and deafened for 1 minute. A feranth can use this ability once every 1d4 rounds. This is a sonic effect, and the save DC is Constitution-based."}],"description":"A feranth uses its devastating sonic attack to incapacitate foes and follows up with its powerful bite, vicious claws, and sharp horns to tear its prey asunder. This massive ambush predator is covered with hardened ridges and mottled black skin. Its limbs end in powerful claws that it uses to dig through tough terrain. When burrowing, a feranth uses its rear legs to smash the sides of its burrow, collapsing the passage behind it. A feranth's head is adorned with two massive, forward-facing horns and four bulbous, constantly humming sacs that amplify its mighty roars. A feranth stands 25 ft. tall and 40 ft. long, and weighs between 9 and 11 tons.\n\nEcology\n\nThe feranths that now roam Numeria are the descendants of a group that were abducted from a far-off planet and brought to Golarion as part of an ill-fated voyage. They remained locked in their containment pods for many years after their arrival on Golarion, but the damage sustained by the pods eventually became too much-they finally failed, releasing the feranths into the unsuspecting world. Using their sharp claws, the creatures burrowed through the structurally weakened hull of the starship in which they were contained, emerging onto the surface of a strange new planet.\n\nOn their native planet, feranths were apex predators that devoured prey with endless appetite, and the few living on Golarion remain true to this behavior. Feranths move on to a new location only after exhausting most sources of available food. While feranths do eventually return to previous hunting grounds, they instinctively wait many years for food sources to replenish before terrorizing those regions once again.\n\nBecause of feranths' highly territorial nature, battles between two rivals are vicious affairs that can take hours or even days to resolve, and almost invariably end with one of the combatants bloodied, limping, and nearly dead. Yet deaths are surprisingly rare during these trials, despite the ferocity with which they are fought. It seems that feranths prefer to simply frighten and weaken their rivals rather than killing them outright.\n\nWhen hunting prey, feranths tend to use ambush tactics. They often charge up through the ground once they have pinpointed their prey's location using tremorsense, and then unleash a mighty roar to further discombobulate their victims. Feranths often repeat this tactic many times during an encounter with prey, diving beneath the ground only to erupt back up a few seconds or even minutes later.\n\nFortunately for the inhabitants of Numeria, female feranths are rare on Golarion-a fact that keeps the beasts' numbers low. It's uncertain whether this same discrepancy in the ratio between the sexes exists on the feranths' home planet. Females are by far the most ferocious members of the species, especially in the few months following the hatching of their eggs. During this time, a female feranth can be identified by her mottled red-brown skin tone and vicious temperament. For 3 months after their eggs hatch, female feranths have the blood rage universal monster ability. A female usually mates multiple times during her lifetime, laying two eggs each time. She cares for her offspring for 3 years before the juveniles abandon their mother, leaving in search of their own territories in which to hunt. Juvenile feranths that have just left their families are often about 12 ft. tall and 20 ft. long.\n\nHabitat & Society\n\nScholars believe that feranths' behavior on Golarion is much the same now as it was on their home planet, with one key difference: their range. Rather than roaming great swaths of territory like their ancestors did, feranths on Golarion remain primarily in Numeria. Some of these creatures have wandered into the Worldwound, however, and every now and then one rampages through the northern reaches of the River Kingdoms, across the southern border of Mendev, or along the eastern edge of Brevoy. For unknown reasons, feranths avoid treading into Ustalav.\n\nFeranths prefer to carve their lairs out of hillsides where they can monitor the passage of potential prey, but\n\nthey sometimes dig dens deep underground to protect themselves from ambush by rival feranths. It is most common for a feranth to construct its home underground when other feranths threaten its territory, but females of the species also dig underground lairs when they are ready to lay and hatch their eggs. Thus, the presence of an underground feranth lair is a sign of greater danger: either the nearby area is infested with other feranths, or the den belongs to a ferocious feranth mother.\n\nCrafty Kellid tribes have learned some tricks, such as the use of earplugs or silencing magic, to counteract the beasts' advantages. They also bait feranths into traps or enclosed canyons using livestock or other large animals. The Kellids use these tactics not only to fight these alien beasts, but also to capture them-a few captive feranths have even been trained for warfare by various tribes. Powerful alchemical concoctions are mixed and fed to a captive feranth, as it is necessary to cloud the creature's mind to tame it. In this state, the feranth becomes docile and seemingly forgets how to burrow, making it easy for the tribe to keep its prized beast nearby. Once the feranth's mind is clouded, blinders can be attached to limit the creature's field of vision, allowing a brave barbarian rider to guide it in battle. When the time comes for the feranth to fight, a second concoction is fed to the beast to give it a burst of energy, sending it into a rampage.\n\nThe Red Dog tribe in Numeria's Sellen Hills was renowned for many years for its control of a feranth, a feat that its leaders parleyed into an alliance between a number of nearby tribes. This alliance-and the entire Red Dog tribe-ended abruptly when the captive feranth eventually developed a tolerance to the alchemical concoctions used to keep it docile.","ecology":"The feranths that now roam Numeria are the descendants of a group that were abducted from a far-off planet and brought to Golarion as part of an ill-fated voyage. They remained locked in their containment pods for many years after their arrival on Golarion, but the damage sustained by the pods eventually became too much-they finally failed, releasing the feranths into the unsuspecting world. Using their sharp claws, the creatures burrowed through the structurally weakened hull of the starship in which they were contained, emerging onto the surface of a strange new planet.\n\nOn their native planet, feranths were apex predators that devoured prey with endless appetite, and the few living on Golarion remain true to this behavior. Feranths move on to a new location only after exhausting most sources of available food. While feranths do eventually return to previous hunting grounds, they instinctively wait many years for food sources to replenish before terrorizing those regions once again.\n\nBecause of feranths' highly territorial nature, battles between two rivals are vicious affairs that can take hours or even days to resolve, and almost invariably end with one of the combatants bloodied, limping, and nearly dead. Yet deaths are surprisingly rare during these trials, despite the ferocity with which they are fought. It seems that feranths prefer to simply frighten and weaken their rivals rather than killing them outright.\n\nWhen hunting prey, feranths tend to use ambush tactics. They often charge up through the ground once they have pinpointed their prey's location using tremorsense, and then unleash a mighty roar to further discombobulate their victims. Feranths often repeat this tactic many times during an encounter with prey, diving beneath the ground only to erupt back up a few seconds or even minutes later.\n\nFortunately for the inhabitants of Numeria, female feranths are rare on Golarion-a fact that keeps the beasts' numbers low. It's uncertain whether this same discrepancy in the ratio between the sexes exists on the feranths' home planet. Females are by far the most ferocious members of the species, especially in the few months following the hatching of their eggs. During this time, a female feranth can be identified by her mottled red-brown skin tone and vicious temperament. For 3 months after their eggs hatch, female feranths have the blood rage universal monster ability. A female usually mates multiple times during her lifetime, laying two eggs each time. She cares for her offspring for 3 years before the juveniles abandon their mother, leaving in search of their own territories in which to hunt. Juvenile feranths that have just left their families are often about 12 ft. tall and 20 ft. long.","habitat_society":"Scholars believe that feranths' behavior on Golarion is much the same now as it was on their home planet, with one key difference: their range. Rather than roaming great swaths of territory like their ancestors did, feranths on Golarion remain primarily in Numeria. Some of these creatures have wandered into the Worldwound, however, and every now and then one rampages through the northern reaches of the River Kingdoms, across the southern border of Mendev, or along the eastern edge of Brevoy. For unknown reasons, feranths avoid treading into Ustalav.\n\nFeranths prefer to carve their lairs out of hillsides where they can monitor the passage of potential prey, but\n\nthey sometimes dig dens deep underground to protect themselves from ambush by rival feranths. It is most common for a feranth to construct its home underground when other feranths threaten its territory, but females of the species also dig underground lairs when they are ready to lay and hatch their eggs. Thus, the presence of an underground feranth lair is a sign of greater danger: either the nearby area is infested with other feranths, or the den belongs to a ferocious feranth mother.\n\nCrafty Kellid tribes have learned some tricks, such as the use of earplugs or silencing magic, to counteract the beasts' advantages. They also bait feranths into traps or enclosed canyons using livestock or other large animals. The Kellids use these tactics not only to fight these alien beasts, but also to capture them-a few captive feranths have even been trained for warfare by various tribes. Powerful alchemical concoctions are mixed and fed to a captive feranth, as it is necessary to cloud the creature's mind to tame it. In this state, the feranth becomes docile and seemingly forgets how to burrow, making it easy for the tribe to keep its prized beast nearby. Once the feranth's mind is clouded, blinders can be attached to limit the creature's field of vision, allowing a brave barbarian rider to guide it in battle. When the time comes for the feranth to fight, a second concoction is fed to the beast to give it a burst of energy, sending it into a rampage.\n\nThe Red Dog tribe in Numeria's Sellen Hills was renowned for many years for its control of a feranth, a feat that its leaders parleyed into an alliance between a number of nearby tribes. This alliance-and the entire Red Dog tribe-ended abruptly when the captive feranth eventually developed a tolerance to the alchemical concoctions used to keep it docile."},{"name":"Flying Polyp","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"aberration","subtypes":["air"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["frightful presence (90 ft., DC 24)"],"ac":29,"ac_touch":16,"ac_flat_footed":26,"ac_mods":"+5 deflection, +2 Dex, +1 dodge, +13 natural, -2 size","hp":207,"hd":"18d8+126","hdvalue":18,"fort":13,"ref":12,"will":16,"defensive_abilities":["amorphous","deflecting winds","partial invisibility"],"dr":"10/magic and slashing","immunities":["acid","cold","sonic"],"sr":25,"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"4 tentacles +21 (1d8+9/19-20 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d8+9"},{"type":"sucking wind"},{"type":"wind blast"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"alter winds"},{"spell":"gust of wind"},{"spell":"whispering wind"},{"spell":"wind walk"}]},{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"whirlwind"}]},{"frequency":"3/day","spells":[{"spell":"control winds"},{"spell":"river of wind"},{"spell":"wind wall"}]}],"strength":28,"dexterity":15,"constitution":24,"intelligence":19,"wisdom":20,"charisma":21,"baseatk":13,"cmb":24,"cmb_special":"+4 vs. grapple","cmd":42,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Fly","value":27},{"skill":"Knowledge (engineering)","value":22},{"skill":"Knowledge (history)","value":22},{"skill":"Knowledge (nature)","value":22},{"skill":"Perception","value":26},{"skill":"Spellcraft","value":25},{"skill":"Stealth","value":15},{"skill":"Use Magic Device","value":23}],"languages":["Aklo"],"environments":["any"],"organizations":["solitary","pair","storm (3-10)"],"treasure":"standard","description_visual":"This nauseating, tapered tower of flesh, eyes, and tendrils writhes midair, surrounded by a strange vortex of sucking wind.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Deflecting Winds","kind":"Su","details":"A flying polyp's mastery over air and wind allows it to surround itself with blasts of precisely aimed gusts, granting the creature a +5 deflection bonus to its Armor Class and a +4 resistance bonus on Reflex saving throws."},{"type":"Partial Invisibility","kind":"Su","details":"A flying polyp's body constantly flickers and shifts, passing from visibility to invisibility in a seemingly random pattern and often not wholly at once, leaving the creature's body in what appear to be multiple sections. This ability, combined with the flying polyp's amorphous, elastic form, makes it difficult to target the creature, granting it a 20% miss chance against all attacks. By concentrating, a flying polyp can become fully invisible."},{"type":"Sucking Wind","kind":"Su","details":"This attack allows the flying polyp to send an eerie wind out to slow and eventually stop a creature's escape. The wind itself isn't particularly strong, but it creates a peculiar sucking sensation as if it were attempting to pull creatures back toward the flying polyp. Activating this ability is a full-round action, and it must concentrate each round to maintain the effect. The sucking wind manifests as a 100-foot-radius spread, with the flying polyp at the center. Each round the polyp maintains concentration, the sucking wind's radius increases by 100 ft., to a maximum radius of a mile. A flying polyp can detect creatures within this area via tremorsense. As a free action, it can increase the effects of the sucking wind on up to five different creatures within the area at one time. Each targeted creature must succeed at a DC 26 Fortitude save each round it remains in the area of the sucking wind or it is slowed until it leaves the area. A creature already under the effects of any slowing effect (such as from this sucking wind or a slow spell) that fails this save is held in place for 1 round-it isn't helpless, but cannot move via any means. Freedom of movement protects against the effects of the sucking wind, and control winds negates its effects in the area of effect of the control winds spell. Natural windstorms or other powerful winds have no effect on a sucking wind. A flying polyp can activate a sucking wind once per day, and can maintain concentration on the effect for up to an hour. The save DC is Constitution-based."},{"type":"Wind Blast","kind":"Su","details":"Once every 1d4 rounds as a standard action, a flying polyp can create a powerful blast of wind at a range of up to 120 ft. This blast of wind creates a sudden explosion of flesh-scouring wind in a 30-foot-radius burst. All creatures within this area take 14d6 points of bludgeoning damage, with a successful DC 26 Reflex save halving the damage. In addition, these winds can check or blow away creatures as if they were tornado-strength winds. The save DC is Constitution-based."}],"description":"A flying polyp is a nauseating mass of flesh, eyes, tentacles, and mouths. A typical flying polyp measures 30 ft. in length but is unusually light for its size, weighing no more than 2,000 pounds. These creatures seem to have no maximum lifespan, but their violent, warlike nature ensures that death eventually occurs-even if it takes eons for the polyp to encounter something capable of defeating it.\n\nA flying polyp is a physical being, but one composed of material strangely unlike the flesh that garbs most living creatures. While the stuff that makes up the exterior of a flying polyp's body might seem similar to ordinary flesh, it often behaves in ways that should be impossible. The material seems to fade in and out of visibility, almost at random, at points becoming transparent enough that the nauseating inner workings of the thing's body are laid bare. Although the polyp feels moist and damp to the touch, what might serve as blood in other creatures behaves more like strange vortices of wind within a flying polyp's body. When wounded, its damaged flesh doesn't bleed so much as whistle and gust. A flying polyp's association with wind goes far beyond the strange storms that surge through what pass as veins and arteries in its massive body. These creatures have a remarkable ability to control the air around them, both via a wide array of spell-like abilities and through the use of potent supernatural powers. They don't wield tools or weapons as a rule, instead using their mastery of the winds themselves to wage war and build their grim cities, scouring towers and chambers out of basalt with precise blasts of sand-laden wind. Although flying polyps display some of the features of other sentient races, particularly in their habit of building cities (although these towering settlements usually incorporate architectural features that most other races find awkward and unsettling), in other areas they seem strangely primitive or uninterested. They are as aberrant in mind and philosophy as they are in physical form. For example, they seem to have neither a name for their own race, nor a language to call their own. Their cities, while bewildering in their vast scale, seem to serve little purpose other than to unnerve, for flying polyps don't engage in trade or politics or other social constructs. The primary exception to this, to the detriment of other creatures unfortunate enough to dwell in regions claimed by flying polyps, is war. Flying polyps excel at genocide, using their mastery over wind to scour clean entire cities and civilizations when they come upon them. Some among their kind can even travel to other planets by bringing with them a sizable sphere of purloined wind to carry them aloft and sustain them, and with this power they lead armies from planet to planet as necessary, relentlessly tracking their chosen enemies across worlds. Every so often, flying polyps encounter a race that is their equal in war, and on some worlds, they still endure the humiliation of these ancient defeats after being imprisoned in extensive underground chambers where they are cut off from the outside world. Yet flying polyps are long-lived, and should unforeseen tectonic events creates new exit to their prison chambers, lost in the forgotten corners of those planets' depths, they emerge with unabated fury to seek revenge against the enemies who dared humiliate them so.","ecology":"","habitat_society":""},{"name":"Gray Goo","cr":14,"xp":38400,"alignment":"N","size":"Fine","type":"construct","subtypes":["swarm"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":29,"ac_touch":29,"ac_flat_footed":18,"ac_mods":"+10 Dex, +1 dodge, +8 size","hp":123,"hd":"19d10+19","hdvalue":19,"fort":8,"ref":18,"will":8,"defensive_abilities":["dispersion","swarm traits"],"immunities":["construct traits","weapon damage"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"swarm (6d6 plus dismantle and distraction)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"dismantle"},{"type":"distraction","details":"DC 21"},{"type":"infest"}],"strength":1,"dexterity":30,"intelligence":5,"wisdom":10,"charisma":1,"baseatk":19,"feats":[{"feat":"Ability Focus (distraction)"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Lightning Reflexes"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lightning Stance"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Wind Stance"}],"skills":[{"skill":"Fly","value":26},{"skill":"Perception","value":13},{"skill":"Stealth","value":32,"special":"(+42 when dispersed) Racial M odifiers +10 Stealth when dispersed"}],"languages":["Common (can't speak)","Hallit (can't speak)"],"environments":["cold plains (Numeria)"],"organizations":["solitary","pair","storm (3-12)"],"treasure":"none","description_visual":"Droplets of a silvery gray, slightly grainy goo gleam dully as they hang in the air.","source":"Numeria Land Of Fallen Stars","special_abilities":[{"type":"Dismantle","kind":"Ex","details":"Creatures damaged by a gray goo must succeed at a DC 19 Reflex save or a random piece of their equipment takes the same amount of damage, determined as though the target rolled a natural 1 on a saving throw, using the rules for items surviving after a saving throw. In addition, unattended objects in the area of a gray goo take damage if the swarm chooses to harm them. The save DC is Constitution-based."},{"type":"Dispersion","kind":"Ex","details":"As an immediate action, a gray goo can disperse, spreading itself across an area of up to 30 cubic ft. While dispersed, it deals no damage and cannot use its other special abilities until it reforms. A dispersed gray goo can hide in plain sight (as a ranger in its favored terrain) with a +10 bonus and doesn't take additional damage from area effects. It takes 2 rounds for a dispersed gray goo to reform."},{"type":"Infest","kind":"Ex","details":"As a standard action, a gray goo can infest a Medium or larger creature (Fortitude DC 21 negates), including constructs and undead. The swarm deals double its normal damage to its host each round, but cannot make use of its dismantle ability. If the host is reduced to 0 hit points while infested, it is reduced to dust and destroyed (similar to a disintegrate effect). A gray goo infesting a host can be expelled by any effect that cures disease, with a disease save equal to this ability's DC. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"Swarms of weaponized nanites-microscopic robots designed to work in large groups to perform varied tasks-roam the Felldales, reducing anything in their path to wisps of dust. Called \"gray goo\" by natives who don't understand the true nature of the creature's components, some swarms were activated as weapons of mass destruction, while others were originally benign swarms that malfunctioned and abandoned their programming. Nanites have limited intelligence and potentially respond to commands. Such controlled swarms often spare the treasure their victims carry.\n\nRumors of virulent clouds of gray goo spread throughout Numeria every few years. The most recent tale speaks of a self-replicating swarm that uses its victims as incubators from which further swarms are born- a harrowing prospect if true.","ecology":"","habitat_society":""},{"name":"Great White Whale","cr":14,"xp":38400,"alignment":"N","size":"Colossal","type":"animal","init":-2,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"low-light vision"}],"ac":28,"ac_touch":0,"ac_flat_footed":28,"ac_mods":"-2 Dex, +28 natural, -8 size","hp":225,"hd":"18d8+144","hdvalue":18,"fort":21,"ref":9,"will":8,"speed":[{"type":"swim","speed":40}],"melee":"bite +25 (6d6+20/19-  20), tail slap +20 (3d6+10)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"capsize"},{"type":"smashing breach"}],"strength":50,"dexterity":6,"constitution":27,"intelligence":2,"wisdom":11,"charisma":5,"baseatk":13,"cmb":41,"cmd":49,"cmd_special":"can't be tripped","feats":[{"feat":"Critical Focus"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Perception","value":13},{"skill":"Swim","value":39}],"sq":[{"type":"hold breath"}],"environments":["any oceans"],"organizations":["solitary","pair","pod (3-16)"],"treasure":"none","description_visual":"This immense whale has an enormous, box-shaped head over a massive, toothy maw. Its rough white hide is laced with scars.","group":"Whale","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Smashing Breach","kind":"Ex","details":"As a full-round action, a great white whale can make a special charge attack against creatures on the surface of the water. At the end of its charge, the whale breaches, then slams down onto the target with incredible force. Any Huge or smaller creatures in the whale's space must make a DC 27 Reflex save or take 4d8+30 points of bludgeoning damage and be forced into the nearest square that is adjacent to the whale. This breach automatically attempts to capsize any boats caught wholly or partially in this area. The save DC is Constitution-based."}],"description":"Legendary in size and temper, great white whales are far more aggressive than their smaller kin.","ecology":"","habitat_society":""},{"name":"Gunpowder Ooze","cr":14,"xp":38400,"alignment":"N","size":"Large","type":"ooze","init":0,"ac":9,"ac_touch":9,"ac_flat_footed":9,"ac_mods":"-1 size","hp":230,"hd":"20d8+140","hdvalue":20,"fort":13,"ref":6,"will":1,"defensive_abilities":["split (slashing or fire, 46 hp)"],"immunities":["cold","ooze traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +23 (1d8+13 plus grab and gunpowder residue)","ranged":"blast +14 touch (4d6+7 plus gunpowder residue)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"combust"},{"type":"constrict","details":"1d8+13"}],"strength":28,"dexterity":11,"constitution":24,"wisdom":1,"charisma":1,"baseatk":15,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":35,"cmd_special":"+4 vs. grapple, can't be tripped","skills":[{"skill":"Climb","value":17}],"environments":["any land"],"organizations":["solitary"],"treasure":"none","description_visual":"This lurching mass of slime and gunpowder leaves a trail of shiny black residue in its wake, and shudders with the concussive energy of an explosive.","source":"Wardens Of The Reborn Forge","special_abilities":[{"type":"Blast","kind":"Ex","details":"Once every 1d4 rounds, a gunpowder ooze can fire a concentrated blast of gunpowder from its body as a ranged touch attack, dealing damage equal to 4d6 + the ooze's Constitution modifier (+7 for most gunpowder oozes). Any creature struck by this blast is also potentially exposed to the ooze's gunpowder residue (Reflex DC 27 negates). This attack has a range of 180 ft. with no range increment. The save DC is Constitution-based."},{"type":"Combust","kind":"Ex","details":"Because of the volatile nature of its composition, a gunpowder ooze is susceptible to combusting when an ignition source is present. Anytime a gunpowder ooze takes fire damage or damage from a ranged firearm attack, it spontaneously explodes, dealing 10d6 points of fire damage to all creatures and objects in a 30-foot-burst cone toward the damage source that ignited the ooze. If there is no method of determining the damage source's direction (such as a burst or spread centered on the ooze), the ooze instead combusts in a 15-foot-radius burst. A successful DC 27 Reflex save halves the damage taken from this attack. A gunpowder ooze that combusts automatically splits. The save DC is Constitution-based."},{"type":"Gunpowder Residue","kind":"Ex","details":"Whenever a gunpowder ooze successfully strikes a creature with its blast or slam attack, the target must succeed at a DC 27 Reflex save to avoid being coated in sticky gunpowder residue. Though the residue isn't harmful in itself, if a creature covered in the residue uses a firearm, wields any weapon capable of dealing fire damage, takes fire damage from any source, or is exposed to a suitable spark, the residue immediately ignites and explodes, dealing 5d6 points of fire damage to the creature. Creatures adjacent to the exploding creature take half damage (Reflex DC 27 half). Gunpowder residue remains flammable for 24 hours, until it is ignited, or until it is scrubbed away (which requires soap, water, and at least 1 hour of bathing and washing). A creature can only be covered in one layer of gunpowder residue at a time. The save DC is Constitution-based."}],"description":"Common throughout the Mana Wastes, where wild magic and gunpowder are both more prevalent than elsewhere in the world, gunpowder oozes are the combination of these two dangerous and unpredictable elements.","ecology":"","habitat_society":""},{"name":"Handmaiden Devil","cr":14,"xp":38400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"ac":31,"ac_touch":17,"ac_flat_footed":24,"ac_mods":"+7 Dex, +14 natural","hp":187,"hd":"15d10+105","hdvalue":15,"fort":16,"ref":16,"will":10,"dr":"10/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":25,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +22 (2d8+7/19-20/x3), 2 tentacles +20 (1d6+3  plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacle)","special_attacks":[{"type":"tentacle cage","details":"4d8+10 bludgeoning, AC 17, 18 hp"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"},{"spell":"spider climb"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"dispel good"},{"spell":"enthrall"},{"spell":"greater teleport","details":"self plus 1 entrapped creature and 50 lbs. of goods only"},{"spell":"persistent image"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 5, 3 erinyes 65%"}]},{"frequency":"3/day","spells":[{"spell":"black tentacles"},{"spell":"charm monster"}]}],"strength":24,"dexterity":25,"constitution":25,"intelligence":22,"wisdom":21,"charisma":20,"baseatk":15,"cmb":22,"cmb_special":"+4 vs. grapple","cmd":39,"cmd_special":"can't be tripped","feats":[{"feat":"Acrobatic Steps"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Multiattack"},{"feat":"Nimble Moves"},{"feat":"Strike Back"}],"skills":[{"skill":"Acrobatics","value":25,"special":"+29 jump"},{"skill":"Bluff","value":23},{"skill":"Diplomacy","value":23},{"skill":"Disguise","value":23},{"skill":"Escape Artist","value":22},{"skill":"Fly","value":14},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (planes)","value":24},{"skill":"Perception","value":23},{"skill":"Perform (sing)","value":23},{"skill":"Sense Motive","value":23},{"skill":"Spellcraft","value":21},{"skill":"Stealth","value":25}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"sq":[{"type":"agile grappler"}],"environments":["any (Hell)"],"organizations":["solitary","retinue (1 gylou and 2d4 erinyes)","cortege (1-4 gylous and 2d10 erinyes)"],"treasure":"standard","description_visual":"Twin tentacles stretch from the crown of this feminine fiend's head, while her lower body blooms in a gown of writhing tendrils.","group":"Devil","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Agile Grappler","kind":"Ex","details":"A gylou doesn't gain the grappled condition if she grapples a foe."},{"type":"Tentacle Cage","kind":"Su","details":"If a gylou successfully grapples a creature, she transfers that creature into her lower body's nest of cage-like tentacles. This works like swallow whole. The gylou's tentacles are AC 17 and have 18 hp for the purpose of an entrapped creature cutting itself out. A gylou's tendrils heal quickly, allowing her to use this ability 1 round after a creature cuts itself free."}],"description":"Known as handmaiden devils, Mothers of Pain, and Maids of Miscarriage, gylous attend to the whims and schemes of Hell's few female overlords. Like manipulative matrons amid decadent mortal courts, these deceivers hide their fathomless evil beneath illusions of beauty, graciousness, and tradition. Gylous particularly loathe children. It's said that the persistent cry of a babe can sometimes cause these fiends to abandon their illusions and viciously attack.\n\nAs greater devils, gylous can command many lesser devils, yet harbor an exclusive favoritism for erinyes. A gylou weighs 160 pounds and stands stiff ly at 5-1/2 ft.- though many wear their head-sprouting tentacles in tall, elaborate coiffures.","ecology":"","habitat_society":""},{"name":"Ice Yai","cr":14,"xp":38400,"alignment":"CE","size":"Large","type":"outsider","subtypes":["cold","oni","giant","native","shapechanger"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":27,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +11 natural, -1 size","hp":200,"hd":"16d10+112","hdvalue":16,"hp_mods":["regeneration 5 (fire or acid)"],"fort":17,"ref":7,"will":12,"immunities":["cold"],"sr":25,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":50},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"4 slams +24 (2d8+9)","ranged":"icy missile +17 touch (4d6 cold)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"staggering strikes"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"},{"spell":"mage armor"}]},{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"polar ray"},{"spell":"solid fog"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"cone of cold"},{"spell":"deep slumber"},{"spell":"gaseous form","details":"self only"}]}],"strength":29,"dexterity":14,"constitution":25,"intelligence":12,"wisdom":15,"charisma":18,"baseatk":16,"cmb":26,"cmd":39,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":23},{"skill":"Disguise","value":14},{"skill":"Fly","value":25},{"skill":"Intimidate","value":23},{"skill":"Knowledge (arcana)","value":11},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":17,"special":"+21 in snow"},{"skill":"Use Magic Device","value":14}],"languages":["Common","Giant"],"sq":[{"type":"change shape","details":"Medium or Large humanoid; alter self or giant form I"}],"environments":["cold mountains"],"organizations":["solitary","gang (1 plus 4-16 frost giants)"],"treasure":"standard","description_visual":"This blue-skinned giant has three eyes, fangs, and claws. Its hair seems to be formed of delicate strands of ice.","group":"Oni","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Icy Missile","kind":"Su","details":"As a swift action, the ice yai can fire a dart of ice from its third eye. This dart is a ranged touch attack (+20 attack bonus), dealing 4d6 points of cold damage on a hit. This attack has a range of 180 ft. with no range increment."},{"type":"Staggering Strikes","kind":"Ex","details":"An ice yai can strike twice per round with its two slam attacks. A creature struck by more than two of these slam attacks in a round must succeed at a DC 27 Fortitude save or be staggered for 1 round. The save DC is Strength-based."}],"description":"The ice yai is a sinister creature that combines the brutality of a frost giant with the grace and style of a skilled martial artist. Although its magical powers are formidable, it prefers to fight in melee using its slam attacks, leading its minions in merciless combat. It uses its mobility to cast combat spells or launch shards of ice from its third eye.\n\nAn ice yai is a natural leader among frost giants, tempering their savagery with its own wisdom. A tribe led by an ice yai may still raid settlements of neighboring humanoids, but the tribe soon learns the value of establishing regular tributes and willing sacrifices-the ice yai teach that methods that rely upon the threat of violence are often even more effective than actual violence. Despite this strangely enlightened philosophy, an ice yai never passes up an opportunity to reinforce its capacity for slaughter, and will often demand that its subjects take part in show battles, both for the entertainment of the tribe and to nurture the ice yai's insatiable ego and sense of dominion over its subjects.","ecology":"","habitat_society":""},{"name":"Indarugant","cr":14,"xp":38400,"alignment":"CE","size":"Huge","type":"undead","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":29,"ac_touch":11,"ac_flat_footed":26,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +14 natural, -2 size","hp":190,"hd":"20d8+100","hdvalue":20,"fort":10,"ref":10,"will":16,"defensive_abilities":["channel resistance +4"],"dr":"5/-","immunities":["cold","undead traits"],"sr":25,"speed":[{"type":"land","speed":30,"special":"40 ft. without armor"}],"melee":"battleaxe +23 (3d6+15/19-20/x3) or   2 slams +23 (1d8+10 plus curse of frozen flesh)","ranged":"rock +16 (2d6+10)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"curse of frozen flesh"},{"type":"lingering curses"},{"type":"rock throwing","details":"120 ft."}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ill omen"}]},{"frequency":"1/day","spells":[{"spell":"cone of cold"}]},{"frequency":"3/day","spells":[{"spell":"bestow curse"},{"spell":"blindness/deafness"}]}],"strength":31,"dexterity":14,"intelligence":12,"wisdom":19,"charisma":19,"baseatk":15,"cmb":27,"cmd":40,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Intimidating Prowess"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":17},{"skill":"Intimidate","value":37},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":14},{"skill":"Survival","value":24}],"languages":["Common","Giant"],"environments":["cold mountains"],"organizations":["solitary","warband (1 indarugant and 2-6 taiga giants)"],"treasure":"standard (hide armor, spear)","description_visual":"Taut, leathery skin clings to the skeleton of this giant, whose hide garments only partially conceal the simple geometric tattoos and ancient battle scars that decorate his flesh.","source":"AP 94","special_abilities":[{"type":"Curse of Frozen Flesh","kind":"Su","details":"Slam-contact; save Will DC 24; effect Creature gains vulnerability to cold. Anytime the cursed creature fails a saving throw against a spell or effect with the cold descriptor, it is also slowed for 1d4 rounds."},{"type":"Lingering Curses","kind":"Su","details":"An indarugant is an accursed creature, and so has dominion over misfortune and curses. An indarugant can apply the effects of its curse of frozen flesh with its bestow curse spell-like ability (in place of bestow curse's normal effects). Additionally, the DC of any attempt to remove a curse inflicted by the indarugant increases by 5. If a caster level check to remove an indarugant's curse fails by 5 or more, the curse appears to be lifted and is temporarily suppressed until the next time the victim enters combat or is otherwise faced with a life-threatening situation (subject to the GM's discretion)."}],"description":"In times of need, the taiga giants of Varisia turn to the spirits of their ancestors for aid, relying on signs and omens from the spirit world to guide them out of danger. Yet sometimes the power and insight of these ancestral spirits isn't enough. When invaders overhunt the land, when disease and pestilence run rampant, or when war and slavery threaten to decimate\n\nwhole tribes, some giants seek a different sort of aid-one that comes at a far higher price. High above the snow line, trapped within ancient glacial floes, the indarugants wait to be unleashed so they might once again bring disaster and ruin to the enemies of their tribes.\n\nMost indarugants resemble the desiccated corpses of taiga giants, though other types of giants may become indarugants as well. After taiga giants, stone giants are the most likely to follow through with this ritual, though by doing so they risk being shunned by neighboring tribes.\n\nIndarugants stand 20 ft. tall, but weigh only 3,000 pounds due to the lack of water in their shriveled, skeletal bodies. The ritual that creates an indarugant involves marking and maiming the body of the candidate, and many still bear these fading tattoos and ancient scars.\n\nEcology\n\nIndarugants are remarkable among corporeal undead in that they can't be created from a deceased creature's corpse-a creature must be alive and willing to be transformed into an indarugant. This process usually begins with a pilgrimage of a group of taiga giants into the icy mountains. The tribe's shaman or chieftain accompanies the candidate in order to perform the profane rituals necessary for the transformation. Once above the snow line, the candidate is subjected to a week-long ritual designed to sever its connection to the spirits of its ancestors, the intent being that the future indarugant can do whatever must be done to protect the tribe without fear of offending the spirits or bringing dishonor to the tribe. At the ritual's conclusion, the candidate is killed with a single blow to the head, then buried in the ice and snow along with the weapons and tools it will use once it rises as an indarugant. How long it takes the indarugant to rise varies-some rise as early as the following evening, while others remain in the ice for months or even years.\n\nNot all giants who agree to undergo the transformation successfully complete their promise. Many lose their gall at the ritual's outset and attempt to escape back down the mountain to safety. Those who flee are hunted ruthlessly by their fellow pilgrims and the rest of the tribe, who fear offending the spirits. If possible, such escapees are captured alive and brought back to the frozen heights to undergo the ritual at spear point. This forced ritual doesn't produce an indarugant, but serves as a deterrent to those who would think to renege on their commitments in the future.\n\nSome tribal leaders claim that those who successfully escape their promise to serve as an indarugant are cursed. They say that these traitors to their people transform into even more grotesque and sinister creatures, though no evidence of such monsters exists-these claims are widely thought to be a scare tactic to elicit compliance.\n\nThose that successfully undergo the transformation come back changed. They are no longer constrained by moral concerns such as honor, fear, or mercy. Indarugants are capable of committing any act, no matter how taboo, so long as it furthers the interests of the tribe and its people. They treat their foes with such brutality that even the most wicked of giants cringe at the sight.\n\nHabitat & Society\n\nIndarugants reside high in the mountains of Varisia, in places where the snow never melts. They hide themselves away in glacial caves, deep foreboding crevasses, and other secluded chasms where only those initiated into the secrets of their creation will know to find them. In times of need, a giant shaman or oracle will journey to the hidden places, braving the dangers of the cold and high elevation in order to beseech the indarugants for aid. Usually this aid comes in the form of exacting violence against the tribe's enemies, as indarugants are powerful warriors and cunning strategists. Rarely, an especially evil or desperate tribe may entreat an indarugant to serve as its chief or shaman, though usually only for a limited period of time, and only when the tribe is leaderless and under dire threat.\n\nWhatever form the indarugant's aid takes, it comes at a steep price. A giant who would petition an indarugant for aid must first swear a profane pact with the creature to someday undergo the transformation and become an indarugant itself. Once the indarugant has accomplished its agreed-upon task, it will lead the petitioner back up the mountain to its desolate home, and perform the necessary rituals to add the petitioner to the ranks of the undead. This serves both as a deterrent to keep the giants from calling on the indarugants too readily, and as a way to ensure the indarugant population grows along with the tribe. In this way, the tribes of giants will always have guardians waiting for them in the high ice, ready to defend them against any threat.\n\nScholars of giant lore claim that all the races of giants once buried their dead in this manner, or at least created indarugants through similar rituals, if they did not live in icy climates. In Varisia, this changed during the Age of Legend, when the runelords of Azlant enslaved the giants and bent them to their sinister will. Those giants who fought back against the runelords called upon the might of their undying ancestors, sending legions of indarugants down into the plains to defend the giant tribes. Though the undead guardians fought fiercely, they were unable to stand against the might of Thassilon, and all were eventually destroyed. Since that time, only the taiga giants, who largely escaped slavery, continue the practice of creating indarugants. This may not be true for much longer, however, as reports of stone and frost giants burying their dead in the high ice now grow ever more common.","ecology":"Indarugants are remarkable among corporeal undead in that they can't be created from a deceased creature's corpse-a creature must be alive and willing to be transformed into an indarugant. This process usually begins with a pilgrimage of a group of taiga giants into the icy mountains. The tribe's shaman or chieftain accompanies the candidate in order to perform the profane rituals necessary for the transformation. Once above the snow line, the candidate is subjected to a week-long ritual designed to sever its connection to the spirits of its ancestors, the intent being that the future indarugant can do whatever must be done to protect the tribe without fear of offending the spirits or bringing dishonor to the tribe. At the ritual's conclusion, the candidate is killed with a single blow to the head, then buried in the ice and snow along with the weapons and tools it will use once it rises as an indarugant. How long it takes the indarugant to rise varies-some rise as early as the following evening, while others remain in the ice for months or even years.\n\nNot all giants who agree to undergo the transformation successfully complete their promise. Many lose their gall at the ritual's outset and attempt to escape back down the mountain to safety. Those who flee are hunted ruthlessly by their fellow pilgrims and the rest of the tribe, who fear offending the spirits. If possible, such escapees are captured alive and brought back to the frozen heights to undergo the ritual at spear point. This forced ritual doesn't produce an indarugant, but serves as a deterrent to those who would think to renege on their commitments in the future.\n\nSome tribal leaders claim that those who successfully escape their promise to serve as an indarugant are cursed. They say that these traitors to their people transform into even more grotesque and sinister creatures, though no evidence of such monsters exists-these claims are widely thought to be a scare tactic to elicit compliance.\n\nThose that successfully undergo the transformation come back changed. They are no longer constrained by moral concerns such as honor, fear, or mercy. Indarugants are capable of committing any act, no matter how taboo, so long as it furthers the interests of the tribe and its people. They treat their foes with such brutality that even the most wicked of giants cringe at the sight.","habitat_society":"Indarugants reside high in the mountains of Varisia, in places where the snow never melts. They hide themselves away in glacial caves, deep foreboding crevasses, and other secluded chasms where only those initiated into the secrets of their creation will know to find them. In times of need, a giant shaman or oracle will journey to the hidden places, braving the dangers of the cold and high elevation in order to beseech the indarugants for aid. Usually this aid comes in the form of exacting violence against the tribe's enemies, as indarugants are powerful warriors and cunning strategists. Rarely, an especially evil or desperate tribe may entreat an indarugant to serve as its chief or shaman, though usually only for a limited period of time, and only when the tribe is leaderless and under dire threat.\n\nWhatever form the indarugant's aid takes, it comes at a steep price. A giant who would petition an indarugant for aid must first swear a profane pact with the creature to someday undergo the transformation and become an indarugant itself. Once the indarugant has accomplished its agreed-upon task, it will lead the petitioner back up the mountain to its desolate home, and perform the necessary rituals to add the petitioner to the ranks of the undead. This serves both as a deterrent to keep the giants from calling on the indarugants too readily, and as a way to ensure the indarugant population grows along with the tribe. In this way, the tribes of giants will always have guardians waiting for them in the high ice, ready to defend them against any threat.\n\nScholars of giant lore claim that all the races of giants once buried their dead in this manner, or at least created indarugants through similar rituals, if they did not live in icy climates. In Varisia, this changed during the Age of Legend, when the runelords of Azlant enslaved the giants and bent them to their sinister will. Those giants who fought back against the runelords called upon the might of their undying ancestors, sending legions of indarugants down into the plains to defend the giant tribes. Though the undead guardians fought fiercely, they were unable to stand against the might of Thassilon, and all were eventually destroyed. Since that time, only the taiga giants, who largely escaped slavery, continue the practice of creating indarugants. This may not be true for much longer, however, as reports of stone and frost giants burying their dead in the high ice now grow ever more common."},{"name":"Juggernaut Beetle","cr":14,"xp":38400,"alignment":"N","size":"Huge","type":"magical beast","init":-1,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"-1 Dex, +22 natural, -2 size","hp":210,"hd":"20d10+100","hdvalue":20,"fort":17,"ref":11,"will":7,"defensive_abilities":["selective mind"],"immunities":["acid","mind-affecting effects"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"bite +28 (4d10+15/19-20)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. cone, 8d6 acid damage, Reflex DC 25 half, usable once every 1d4 rounds"},{"type":"trample","details":"2d8+15, DC 30"}],"strength":31,"dexterity":9,"constitution":20,"intelligence":2,"wisdom":13,"charisma":8,"baseatk":20,"cmb":32,"cmb_special":"+2 vs. bull rush","cmd":41,"cmd_special":"+2 vs. bull rush or trip","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":23},{"skill":"Perception","value":14}],"environments":["any underground"],"organizations":["single","pair"],"treasure":"none","description_visual":"This massive insect lumbers ominously, waving scythe-like mandibles that reek of acid.","group":"Beetle","source":"Monster Codex","special_abilities":[{"type":"Selective Mind","kind":"Su","details":": To anyone but duergar, these beetles count as mindless. Duergar can affect them with mind-affecting effects, and train and control them as if the beetles were animals."}],"description":"One duergar steers a juggernaut while two riders attack.","ecology":"","habitat_society":""}];
